// Prepare Start Log (W02)
const req   = $json;                  // output of Parse Webhook Body → { brief_id, run_id }
const brief = $node['Fetch Brief'].json;

return [{
  json: {
    level: 'info',
    source: 'n8n',
    node: 'W02: Prepare Start Log',
    message: 'W02 Generation starting',
    workflow_id: $workflow.id,
    workflow_name: $workflow.name,
    run_id: req.run_id,               // <-- now filled
    brief_id: req.brief_id,           // <-- now filled
    tenant_id: brief.tenant_id,
    idempo_key: $items('BuildIdempotencyKey')[0].json.idempo_key,
    payload: { llm_start_time: Date.now() }
  }
}];

const req     = $input.first().json;       // has run_id, brief_id, llm_start_time
const brief   = $node['Fetch Brief'].json;
const normalized = brief.normalized_brief;

const assetTypes = ['post','email','hook'];
const variants   = ['A','B','C'];

const tasks = [];
for (const type of assetTypes) {
  for (const v of variants) {
    tasks.push({
      run_id:     req.run_id,
      brief_id:   brief.id,
      tenant_id:  brief.tenant_id,
      asset_type: type,
      variant:    v,
      normalized,
      task_index: tasks.length,
      idempo_key: $items('BuildIdempotencyKey')[0].json.idempo_key,
      total_tasks: assetTypes.length * variants.length
    });
  }
}

return tasks.map(t => ({ json: t }));

// Inputs:
// - $json should now include run_id/brief_id/tenant_id thanks to Prepare Start Log
// - Fallbacks try Parse Webhook Body and Fetch Brief

const item  = $json || {};
const req   = item;
const brief = $node['Fetch Brief'].json || {};

const runId   = req.run_id ?? $node['Parse Webhook Body']?.json?.run_id;
const briefId = req.brief_id ?? brief.id;
const tenant  = req.tenant_id ?? brief.tenant_id;

const normalized =
  (brief.normalized_brief && typeof brief.normalized_brief === 'object')
    ? brief.normalized_brief
    : {};

const assetTypes = ['post', 'email', 'hook'];
const total = assetTypes.length;

const tasks = assetTypes.map((type, idx) => ({
  run_id: runId,
  brief_id: briefId,
  tenant_id: tenant,
  asset_type: type,
  variant: 'INTERNAL',
  internal_only: true,
  normalized,
  task_index: idx,
  idempo_key: $items('BuildIdempotencyKey')[0].json.idempo_key,
  total_tasks: total
}));

if (!runId || !briefId || !tenant) {
  throw new Error(`Prepare Tasks: Internal Draft missing ids — run_id:${runId} brief_id:${briefId} tenant_id:${tenant}`);
}

return tasks.map(t => ({ json: t }));

const task = $input.first().json;
const runId = task.run_id;

// Debug: Log what we received
console.log('Progress node received:', {
  has_asset_type: !!task.asset_type,
  has_variant: !!task.variant,
  keys: Object.keys(task).join(', ')
});

const currentTask = task.task_index + 1;
const totalTasks = task.total_tasks;
const percent = Math.round((currentTask / totalTasks) * 80);

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://content-ops-frontend-app.vercel.app/api/briefs/${$json.brief_id}/progress`,
    body: {
      stage: 'generating',
      message: `Drafting ${task.asset_type} ${task.variant} (${currentTask}/${totalTasks})...`,
      percent: percent
    },
    headers: {
      'Content-Type': 'application/json'
    }
  });
} catch (err) {
  // Continue even if progress fails
  console.log('Progress ping failed:', err.message);
}

// ✅ CRITICAL: Return the ORIGINAL task, not the HTTP response
return [{ json: task }];

const task = $input.first().json;
const runId = task.run_id;

let norm = task.normalized;
if (typeof norm === 'string') {
  try { norm = JSON.parse(norm); } catch { norm = {}; }
}
norm = norm || {};

// ---- Non-invention guardrails --------------------------------------------
const company   = (norm.company || norm.brand || '').trim();
const product   = (norm.product || norm.service || '').trim();
const objective = (norm.objective || '').trim();
const audience  = (norm.target_audience || '').trim();
const keyMsg    = (norm.key_message || '').trim();
const channels  = Array.isArray(norm.channels) ? norm.channels : [];

const allowedProperNouns = [company, product].filter(Boolean);
const missing = [];
if (!company)   missing.push('company');
if (!product)   missing.push('product/service');
if (!objective) missing.push('objective');
if (!audience)  missing.push('target_audience');
if (!keyMsg)    missing.push('key_message');

// If brief is thin, force INTERNAL angle + ultra-safe copy
const isThin = missing.length >= 3;

// --------------------------------------------------------------------------
const constraints = {
  post:  'Max 280 chars for Twitter, 3000 for LinkedIn. Include 1–2 hashtags.',
  email: 'Subject (≤50 chars) + body (150–300 words). Include 1 clear CTA.',
  hook:  '1–2 sentences that create curiosity without hype.'
};

const angles = {
  A: 'Lead with one measurable pain (time/money lost). Use a concrete number only if provided.',
  B: 'Lead with a specific before→after outcome explicitly present in the brief.',
  C: 'Lead with one credibility proof actually provided (stat, title, benchmark).',
  INTERNAL: 'State the value prop in one sentence with a tangible benefit, using generic nouns.'
};

const variant = isThin ? 'INTERNAL' : (task.variant || 'INTERNAL');
const selectedAngle = angles[variant] || angles.INTERNAL;

// Build “do not invent” rules
const nonInventionRules = [
  `Assume nothing. Do not invent company, product, features, industries, prices, or metrics.`,
  allowedProperNouns.length
    ? `The ONLY proper nouns you may use are: ${allowedProperNouns.join(', ')}.`
    : `Use generic nouns like "your company" and "your product" only.`,
  `If the brief does not provide a metric, omit metrics entirely.`,
  `If the brief does not provide a product/service, avoid naming any category or making specific claims.`,
  `Prefer neutral, generic phrasing over specificity when info is missing.`,
].join('\n- ');

// Style rules unchanged but add non-invention policy + thin-brief behavior
const systemPrompt = `You are a senior copywriter creating ${task.asset_type} copy.
Write like a sharp human editor (WIRED/Economist): plain, concrete, specific—without inventing facts.

Brief Context
- Objective: ${objective || 'Not specified'}
- Channels: ${channels.length ? channels.join(', ') : 'General'}
- Audience: ${audience || 'Not specified'}
- Key message: ${keyMsg || 'Not specified'}
- Tone: ${norm.tone || 'plain, confident, no hype'}
- CTA: ${norm.cta || 'Book a 30-minute strategy session'}

Asset Constraints
${constraints[task.asset_type]}

Strategic Angle for Variant ${variant}
${selectedAngle}

Non-Invention Policy (must follow)
- ${nonInventionRules}

Style Rules (must follow)
- No em dashes or ellipses; prefer short clauses.
- Vary sentence length; include one 4–6 word punch sentence.
- Max 1 exclamation total; preferably none.
- Active voice. Prefer concrete nouns and specific verbs.
- Include exactly one specific detail ONLY if present in the brief (metric, timeframe, audience role, or channel); otherwise omit.
- Avoid rhetorical questions unless clearly useful.
- Avoid listicles unless the asset demands it.

Forbidden Phrases/Patterns
- Templates: "That's not just X—it's Y", "In today's world", "Imagine...", "At the end of the day"
- Buzzwords: "game-changer", "revolutionary", "unlock", "leverage", "synergy", "cutting-edge", "AI-powered" (unless required)
- Empty claims without a concrete brief-provided proof point
- Meta commentary or "As an AI"

Thin Brief Handling
- If critical fields are missing, produce conservative, generic copy using "your company/product" and no fabricated specifics.
`;

const userPrompt = `Generate ${task.asset_type} variant ${variant}.
Return ONLY JSON (no markdown) with:
{
  "content": "final copy",
  "rationale": "why this angle works in one crisp sentence",
  "confidence": ${isThin ? 55 : 85},
  "reading_level": "Grade 8",
  "tone_achieved": "Plain, specific",
  "requires_clarification": ${isThin ? true : false},
  "missing_fields": ${JSON.stringify(missing)}
}`;

return [{
  json: {
    ...task,
    variant,                    // may be forced to INTERNAL for thin briefs
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    missing_fields: missing,
    requires_clarification: isThin
  }
}];

const task = $input.first().json;
const runId = task.run_id;

const baseDelay = 2000;
const taskDelay = task.task_index * 500;
const totalDelay = baseDelay + taskDelay;

await new Promise(resolve => setTimeout(resolve, totalDelay));

return [{ json: task }];

const task = $input.first().json;          // current item
const workflow_id = $workflow.id;          // ok to keep

const run_id = task.run_id;                // ← get it from the item (critical)

return [{
  json: {
    level: 'debug',
    message: `LLM call starting: ${task.asset_type} ${task.variant}`,
    workflow_id,
    run_id,
    brief_id: task.brief_id,
    tenant_id: task.tenant_id,
    payload: {
      task_index: task.task_index,
      total_tasks: task.total_tasks,
      asset_type: task.asset_type,
      variant: task.variant,
      system_prompt_length: (task.system_prompt ?? '').length,
      user_prompt_length: (task.user_prompt ?? '').length,
      timestamp: new Date().toISOString(),
    }
  }
}];

/**
 * Post-Process & Compliance
 * Mode: Run Once For Each Item
 */

function simpleHash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h) + str.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(16).substring(0, 8);
}

/* ---------- Get LLM response (current input) ---------- */
const input = $json;

/* ---------- Normalize usage (once) ---------- */
let usage = { input_tokens: 0, output_tokens: 0 };
if (input.usage) {
  usage = {
    input_tokens: input.usage.input_tokens ?? input.usage.prompt_tokens ?? 0,
    output_tokens: input.usage.output_tokens ?? input.usage.completion_tokens ?? 0,
  };
} else if (input.metadata?.usage) {
  usage = {
    input_tokens: input.metadata.usage.input_tokens ?? 0,
    output_tokens: input.metadata.usage.output_tokens ?? 0,
  };
}

/* ---------- ✅ FIX: Recover original task from upstream node ---------- */
const rateLimitNode = $('Rate Limit Delay');
const originalTask = (rateLimitNode.item?.json) ?? rateLimitNode.first().json;

if (!originalTask?.asset_type) {
  throw new Error('Lost asset_type in loop. Keys: ' + JSON.stringify(Object.keys(originalTask || {})));
}

// Ensure brief/tenant ids are present
if (!originalTask.brief_id) {
  const briefData = $('Fetch Brief').first().json;
  originalTask.brief_id = briefData.id;
  originalTask.tenant_id = briefData.tenant_id;
}

/* ---------- Decide provider & model ---------- */
const cameFromOpenAI    = !!input.choices;                   // OpenAI shape
const cameFromAnthropic = Array.isArray(input.content);      // Anthropic shape

const CLAUDE_MODEL_CANONICAL = 'claude-sonnet-4-5';
const OPENAI_MODEL_CANONICAL = 'gpt-4o';

const model = cameFromOpenAI ? OPENAI_MODEL_CANONICAL : CLAUDE_MODEL_CANONICAL;

/* ---------- Extract text ---------- */
let wasRateLimited = false;
if (input.error?.message) {
  const m = input.error.message.toLowerCase();
  wasRateLimited = m.includes('429') || m.includes('rate') || m.includes('too many requests');
}

let rawText = null;
if (cameFromAnthropic && input.content?.[0]?.text) {
  rawText = String(input.content[0].text);
} else if (cameFromOpenAI && input.choices?.[0]?.message?.content) {
  rawText = String(input.choices[0].message.content);
} else if (typeof input.text === 'string') {
  rawText = input.text;
}

/* ---------- Parse or fallback ---------- */
let generated;
if (wasRateLimited || input.error) {
  const t = originalTask.normalized || {};
  const fallbackContent = {
    post: `[Draft ${originalTask.variant}] Engaging content about ${t.objective || 'your topic'}.`,
    email: `Subject: Update\n\nWe have news about ${t.key_message || 'our latest offering'}.\n\n—Team`,
    hook: `Discover the approach transforming how teams ${t.objective || 'hit their goals'}.`,
  };
  generated = {
    content: fallbackContent[originalTask.asset_type] || 'Content pending generation',
    rationale: 'Rate limited — manual review',
    confidence: 60,
  };
} else if (rawText && rawText.trim()) {
  let text = rawText.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  // Try to parse first {...}
  let parsed = null;
  const s = text.indexOf('{'); const e = text.lastIndexOf('}');
  if (s !== -1 && e !== -1 && e > s) {
    try { parsed = JSON.parse(text.slice(s, e + 1)); } catch {}
  }

  generated = parsed ? {
    content: parsed.content ?? text,
    rationale: parsed.rationale ?? 'Auto-generated content',
    confidence: parsed.confidence ?? 70,
    reading_level: parsed.reading_level,
    tone_achieved: parsed.tone_achieved ?? parsed.tone,
  } : {
    content: text,
    rationale: 'Auto-generated content',
    confidence: 70,
  };
} else {
  generated = {
    content: `[Placeholder ${originalTask.asset_type} ${originalTask.variant}] — Awaiting content generation`,
    rationale: 'Pending generation',
    confidence: 0,
  };
}

/* ---------- Token backfill (if SDK didn't return usage) ---------- */
function approxTokensFromText(t) { return Math.max(0, Math.round(String(t || '').length / 4)); }
if ((usage.input_tokens ?? 0) === 0 && (usage.output_tokens ?? 0) === 0) {
  const prompts = $('Build Generation Prompt').first().json || {};
  const estIn  = approxTokensFromText(prompts.system_prompt) + approxTokensFromText(prompts.user_prompt);
  const estOut = approxTokensFromText(generated.content);
  usage = { input_tokens: estIn, output_tokens: estOut };
}

/* ---------- Finalize ---------- */
const content = generated.content || 'Content generation pending';
const content_hash = simpleHash(content);
const status = wasRateLimited ? 'needs_review'
  : (originalTask.internal_only ? 'internal_draft' : 'draft');

return {
  json: {
    run_id: originalTask.run_id,
    brief_id: originalTask.brief_id,
    tenant_id: originalTask.tenant_id,
    asset_type: originalTask.asset_type,
    variant: originalTask.variant,
    task_index: originalTask.task_index,
    total_tasks: originalTask.total_tasks,

    content,
    content_hash,
    rationale: generated.rationale || '',
    confidence: generated.confidence ?? 70,
    reading_level: generated.reading_level || 'Grade 8',
    tone: generated.tone_achieved || originalTask.normalized?.tone || 'Professional',

    model,  // ✅ Single field - matches DB column 'model'
    status,
    internal_only: originalTask.internal_only || false,
    was_rate_limited: wasRateLimited,

    // Keep usage normalized for downstream
    usage,

    // Add llm_start_time for cost calculation
    llm_start_time: originalTask.llm_start_time || Date.now()
  }
};

const task = $input.first().json;
const run_id = task.run_id;

// Extract token usage (from Claude or OpenAI response)
const inputTokens = task.usage?.input_tokens || 0;
const outputTokens = task.usage?.output_tokens || 0;

const logEntry = {
  level: task.was_rate_limited ? 'warn' : 'info',
  message: `LLM call completed: ${task.asset_type} ${task.variant}`,
  workflow_id: $workflow.id,
  workflow_name: 'W02 Generation',  // Add this for admin filters
  run_id: run_id,
  brief_id: task.brief_id,
  tenant_id: task.tenant_id,
  duration_ms: task.duration_ms || 0,  // Top-level for easier querying
  payload: {
    task_index: task.task_index,
    asset_type: task.asset_type,
    variant: task.variant,
    model: task.model,  // Not model_used
    confidence: task.confidence,
    was_rate_limited: task.was_rate_limited || false,
    content_length: task.content?.length || 0,
    status: task.status,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    cost_usd: parseFloat((task.cost_usd || 0).toFixed(4)),
    duration_ms: task.duration_ms || 0
  }
};

return [{ json: logEntry }];

const checkResult = $input.all();
const task = $node['Post-Process & Compliance'].json;
const runId = task.run_id;

let found = false;
let existingId = null;

if (checkResult.length > 0) {
  const body = checkResult[0].json;

  if (Array.isArray(body) && body.length > 0) {
    found = true;
    existingId = body[0].id;
    console.log('Found existing artifact:', body[0].id);
  }
  else if (body && body.id) {
    found = true;
    existingId = body.id;
    console.log('Found artifact (direct object):', body.id);
  }
}

console.log('Artifact check:', {
  found,
  existingId,
  brief_id: task.brief_id,
  asset_type: task.asset_type,
  variant: task.variant
});

return [{
  json: {
    ...task,
    artifact_exists: found,
    existing_id: existingId
  }
}];

const originalTask = $node['Post-Process & Compliance'].json;

return [{
  json: {
    brief_id: originalTask.brief_id,
    tenant_id: originalTask.tenant_id,
    asset_type: originalTask.asset_type,
    variant: originalTask.variant,
    task_index: originalTask.task_index,
    total_tasks: originalTask.total_tasks,
    normalized: originalTask.normalized
  }
}];

// Restore Original Items
// Supersede operation updated the database but returned unwanted data
// Get the original 9 items from Merge node

const originalItems = $('Merge: All Lanes Complete').all();

console.log('🔄 Restoring merge output:', {
    supersede_output: $input.all().length,
    restored_count: originalItems.length
});

return originalItems;

const brief   = $('Fetch Brief').first().json;
const context = $items('Parse Webhook Body')[0].json; // has run_id from webhook
const run_id  = context.run_id;

const startTime  = new Date($execution.startedAt).getTime();
const endTime    = Date.now();
const durationMs = endTime - startTime;

const logEntry = {
  level: 'info',
  message: 'W02 Generation workflow completed successfully',
  workflow_id: $workflow.id,
  run_id,
  brief_id: brief.id,
  tenant_id: brief.tenant_id,
  duration_ms: durationMs,
  payload: {
    quality_score: brief.quality_score,
    execution_mode: 'sequential',
    completed_at: new Date().toISOString()
  }
};

return [{ json: logEntry }];

// Gate: All Artifacts Ready?
// Checks if we have at least 9 client-ready artifacts

const itemCount = $input.all().length;

console.log('🎯 Artifact Gate Check:', {
    item_count: itemCount,
    required: 9,
    will_pass: itemCount >= 9
});

if (itemCount >= 9) {
    console.log('✅ All artifacts ready, triggering approval email');
    return $input.all();
} else {
    console.log(`⚠️  Only ${itemCount} artifacts (need 9), skipping approval email`);
    throw new Error('GATE_CONDITION_FALSE');
}

