// Normalize common Anthropic naming variants
function normalizeModel(m) {
  const s = String(m).toLowerCase();

  // Common aliases you’ve used in W02 already
  if (s.includes('sonnet') && s.includes('3-5')) return 'claude-3-5-sonnet-latest';
  if (s.includes('sonnet') && (s.includes('4-5') || s.includes('45'))) return 'claude-4-5-sonnet-latest';
  if (s.includes('haiku')  && s.includes('3-5')) return 'claude-3-5-haiku-latest';

  // OpenAI variants
  if (s.includes('gpt-4o')) return 'gpt-4o';

  // Fallback to the cheapest safe baseline
  return 'claude-3-5-haiku-latest';
}

const model = normalizeModel(modelRaw);
const usage = $json.usage || { input_tokens: 0, output_tokens: 0 };

// $ per 1M tokens — adjust if your pricing changes
const pricing = {
  'claude-4-5-sonnet-latest': { input: 3.00, output: 15.00 },
  'claude-3-5-sonnet-latest': { input: 3.00, output: 15.00 },
  'claude-3-5-haiku-latest':  { input: 1.00, output:  5.00 },
