};

const defaultRate = { input: 1.00, output: 5.00 }; // ultimate safety net
const rate = pricing[model] || defaultRate;

// Defensive numbers
const inTok  = Number(usage.input_tokens  || 0);
const outTok = Number(usage.output_tokens || 0);

const cost_usd =
  (inTok  / 1_000_000) * rate.input +
  (outTok / 1_000_000) * rate.output;

const duration_ms = Date.now() - ($json.llm_start_time || Date.now());

return [{
  json: {
