if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { throw new Error('Invalid JSON in webhook body'); }
}

const brief_id = body.brief_id;
const run_id   = body.run_id;

// quick UUID v4-ish check (loose but fine)
const UUID_RE = /^[0-9a-fA-F-]{36}$/;

if (!brief_id || !UUID_RE.test(brief_id)) throw new Error('Missing/invalid brief_id (uuid expected)');
if (!run_id   || !UUID_RE.test(run_id))   throw new Error('Missing/invalid run_id (uuid expected)');

// ✅ CRITICAL FIX: Pass through ALL webhook data
console.log('📦 Parse Webhook Body - Full payload:', JSON.stringify(body, null, 2));
return [{ json: body }];

// Attach run_id from webhook to all task items
const runId = $items('Parse Webhook Body')[0].json.run_id;
const briefId = $items('Parse Webhook Body')[0].json.brief_id;

console.log('📎 Attaching context:', { runId, briefId });

return $input.all().map(item => ({
