  model_used: $json.model_used,  // Should be undefined
  cost_usd: $json.cost_usd,
  duration_ms: $json.duration_ms,
  tokens: $json.usage
});

return $json;  // ✅ Just pass through the object

// Token bucket keyed per tenant to avoid bursty spikes
const RAW_URL = String($json.REDIS_URL || '').trim();
const REDIS_URL = RAW_URL.replace(/\/+$/,'');
const REDIS_TOKEN = String($json.REDIS_TOKEN || '').trim();
async function r(cmd, method='GET'){
  const body = await this.helpers.httpRequest({
    method, url: `${REDIS_URL}/${cmd.join('/')}`,
    headers: { Authorization: `Bearer ${REDIS_TOKEN}` }, json: true,
  });
  return body.result;
}

async function take(key, capacity=3, refillPerSec=1){
  const now = Date.now();
  const raw = await r(['GET', `tb:${key}`], 'GET');
  let tokens = capacity, ts = now;
  if(raw){ const [t,tms]=raw.split('|').map(Number); tokens=Math.min(capacity, t + ((now-tms)/1000)*refillPerSec); ts=tms; }
  if(tokens < 1){ const waitMs = Math.ceil((1 - tokens)/refillPerSec*1000); return { allowed:false, waitMs }; }
  tokens -= 1;
  await r(['SET', `tb:${key}`, `${tokens}|${now}`], 'POST');
  return { allowed:true, remaining_tokens:tokens };
}

const tenant = $json.tenant_id ?? 'single';
return [{ json: { ...$json, ...(await take(`w02:${tenant}`)) } }];

